(() => {
  'use strict';
  const keys={garage:'atr-garage-v1',visit:'atr-last-visit-v1',quiz:'atr-quiz-v1'};
  let persistent=true;
  function read(key,fallback){try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw):fallback;}catch{persistent=false;return fallback;}}
  function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{persistent=false;return false;}}
  function validUrl(value){try{const u=new URL(value,location.origin);return (u.origin===location.origin&&/^\/videos\/[a-z0-9_-]+\/$/.test(u.pathname))||(u.origin==='https://www.youtube.com'&&/^\/(watch|shorts\/)/.test(u.pathname));}catch{return false;}}
  let garage=read(keys.garage,[]);if(!Array.isArray(garage))garage=[];
  garage=garage.filter(v=>v&&typeof v.id==='string'&&/^[\w-]{11}$/.test(v.id)&&typeof v.title==='string'&&typeof v.url==='string'&&validUrl(v.url)).slice(0,100);
  let toast;
  function say(message){if(!toast){toast=document.createElement('div');toast.className='storage-toast';toast.setAttribute('role','status');document.body.append(toast);}toast.textContent=message;toast.hidden=false;clearTimeout(say.timer);say.timer=setTimeout(()=>{toast.hidden=true;},4000);}
  function syncButtons(){document.querySelectorAll('[data-save-review]').forEach(b=>{const saved=garage.some(v=>v.id===b.dataset.saveReview);if(b.getAttribute('aria-pressed')!==String(saved))b.setAttribute('aria-pressed',String(saved));const label=saved?'Saved to garage':'Save review';if(b.textContent!==label)b.textContent=label;});document.querySelectorAll('[data-garage-count]').forEach(n=>{if(n.textContent!==String(garage.length))n.textContent=String(garage.length);});}
  function save(video){const exists=garage.some(v=>v.id===video.id);if(!exists&&garage.length>=100){say('Your garage has 100 reviews. Remove one to save another.');return;}garage=exists?garage.filter(v=>v.id!==video.id):[video,...garage];const kept=write(keys.garage,garage);syncButtons();renderGarage();say(kept?(exists?'Removed from your garage.':'Saved. Find it in My Garage next time.'):'Browser storage is unavailable. This watchlist will reset when you leave.');}
  function enhanceCards(){document.querySelectorAll('.video-card[data-video]').forEach(card=>{if(card.querySelector('[data-save-review]'))return;const title=card.querySelector('h3');const url=card.dataset.url;if(!title||!validUrl(url))return;const button=document.createElement('button');button.type='button';button.className='save-review';button.dataset.saveReview=card.dataset.video;button.setAttribute('aria-label','Save review: '+title.textContent);button.addEventListener('click',()=>save({id:card.dataset.video,title:title.textContent.trim().slice(0,300),url}));card.querySelector('.card-copy')?.append(button);});syncButtons();}
  function renderGarage(){const list=document.querySelector('[data-garage-list]');if(!list)return;list.replaceChildren();const note=document.querySelector('[data-storage-status]');if(!persistent&&note)note.textContent='Browser storage is unavailable. Your watchlist will reset when you leave this page.';if(!garage.length){const p=document.createElement('p');p.textContent='An empty garage is full of possibilities. Save a review to start your shortlist.';const a=document.createElement('a');a.className='button';a.href='/long-videos/';a.textContent='Find your first review ↗';list.append(p,a);return;}garage.forEach(v=>{const article=document.createElement('article');article.className='garage-item';const img=document.createElement('img');img.src='/assets/thumbnails/'+v.id+'.jpg';img.alt='';img.width=480;img.height=270;img.loading='lazy';img.addEventListener('error',()=>{img.src='/assets/new-channel-cover.svg';},{once:true});const copy=document.createElement('div');const title=document.createElement('h2');const a=document.createElement('a');a.href=v.url;a.textContent=v.title;title.append(a);const watch=document.createElement('a');watch.href=v.url;watch.className='text-link';watch.textContent='Open review ↗';copy.append(title,watch);const remove=document.createElement('button');remove.className='save-review';remove.type='button';remove.textContent='Remove';remove.setAttribute('aria-label','Remove '+v.title+' from garage');remove.addEventListener('click',()=>{save(v);const next=list.querySelector('button')||list.querySelector('a');next?.focus();});article.append(img,copy,remove);list.append(article);});}
  const prior=read(keys.visit,null);const previous=typeof prior==='number'&&Number.isFinite(prior)?prior:null;
  function welcome(){const message=document.querySelector('[data-return-message]');if(!message)return;const dates=[...document.querySelectorAll('[data-video][data-published]')].map(x=>({id:x.dataset.video,date:Date.parse(x.dataset.published)}));const unseen=new Set(dates.filter(v=>previous&&v.date>previous).map(v=>v.id)).size;const label=previous?(unseen?`Welcome back. ${unseen} new ${unseen===1?'video':'videos'} since your last visit.`:'Welcome back. Your next closer look starts here.'):'New cars. More details. Keep exploring.';if(message.textContent!==label)message.textContent=label;}
  enhanceCards();renderGarage();welcome();write(keys.visit,Date.now());
  let scheduled=false;new MutationObserver(()=>{if(scheduled)return;scheduled=true;queueMicrotask(()=>{scheduled=false;enhanceCards();welcome();});}).observe(document.querySelector('main'),{childList:true,subtree:true});
  window.addEventListener('storage',e=>{if(e.key===keys.garage){let incoming=read(keys.garage,[]);garage=Array.isArray(incoming)?incoming.filter(v=>v&&/^[\w-]{11}$/.test(v.id)&&typeof v.title==='string'&&validUrl(v.url)).slice(0,100):[];syncButtons();renderGarage();}});
  const quiz=document.querySelector('[data-car-quiz]');if(!quiz)return;
  // Evergreen questions rotate in sets of three on Mondays, using Toronto's calendar.
  const bank=[
    ['Which type of hybrid can you recharge from a wall charger?',['A conventional hybrid','A plug-in hybrid','Both, always'],1,'A plug-in hybrid (PHEV) can accept an external charge. A conventional hybrid replenishes its battery while driving.'],
    ['Regenerative braking primarily turns slowing down into…',['Energy stored in the battery','Extra fuel in the tank','More tyre pressure'],0,'An electric motor acts as a generator during deceleration, recovering some energy that would otherwise become heat.'],
    ['In L/100 km, which figure uses less fuel for the same distance?',['9.0 L/100 km','6.0 L/100 km','They are equal'],1,'Lower L/100 km means fewer litres used per 100 kilometres. Keep test conditions comparable.'],
    ['Does all-wheel drive remove the need for suitable winter tyres?',['Yes, on any road','Only in an SUV','No'],2,'AWD helps deliver power to the road. It does not replace the grip suitable tyres provide for braking and turning.'],
    ['Does a bigger infotainment screen guarantee wireless CarPlay?',['Yes','No','Only with navigation'],1,'Screen size does not confirm phone connectivity. Check the exact trim, model year and market, then connect your own phone.'],
    ['What does a lower monthly payment tell you by itself?',['The car costs less overall','The interest rate is lower','Not enough to compare total cost'],2,'A longer loan or a larger down payment can reduce the payment. Compare term, rate, fees, down payment and total paid.'],
    ['What is a blind-spot warning designed to do?',['Replace a shoulder check','Alert you to a detected vehicle','Guarantee the lane is clear'],1,'It is an assistance feature with detection limits. It does not replace checking mirrors and the surrounding road.'],
    ['Which unit describes an EV battery’s energy capacity?',['kWh','kW','km/h'],0,'Kilowatt-hours (kWh) measure energy. Kilowatts (kW) measure power, including charging power.'],
    ['Is a charger’s advertised maximum always your actual charging speed?',['Yes','No','Only above 80% charge'],1,'Actual power depends on the vehicle, battery temperature, state of charge, charger and other conditions.'],
    ['What should you bring to check a car’s phone integration?',['Only a screenshot','Your own phone and cable','A new SIM card'],1,'Try your own phone, cable, navigation and audio before buying. Compatibility and connection modes vary by vehicle.'],
    ['What is the most useful way to check boot space?',['Only compare litres','Only look at the opening','Try the items you actually carry'],2,'Cargo volume is useful, but the shape, opening, loading lip and your own luggage or stroller matter too.'],
    ['Does a Canadian trim name guarantee identical U.S. equipment?',['Yes','No','Only for SUVs'],1,'Equipment and trim names can differ by country and year. Check the specification for the market you are buying in.']
  ];
  const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const part=t=>Number(parts.find(p=>p.type===t).value);const today=new Date(Date.UTC(part('year'),part('month')-1,part('day')));const day=(today.getUTCDay()+6)%7;const monday=new Date(today.getTime()-day*86400000);const week=monday.toISOString().slice(0,10);const cycle=((Math.floor((monday-Date.UTC(2026,9,19))/604800000)%4)+4)%4;const questions=bank.slice(cycle*3,cycle*3+3);const edition=document.querySelector('[data-quiz-edition]');if(edition)edition.textContent='WEEK OF '+monday.toLocaleDateString('en-CA',{month:'short',day:'numeric',timeZone:'UTC'}).toUpperCase();
  let state=read(keys.quiz,{});if(!state||state.week!==week||!Array.isArray(state.answers))state={week,answers:[]};state.answers=state.answers.slice(0,3).filter(a=>Number.isInteger(a)&&a>=0&&a<3);
  function draw(){quiz.replaceChildren();const progress=document.createElement('p');progress.className='quiz-progress';if(state.answers.length===3){const score=state.answers.reduce((sum,a,i)=>sum+(a===questions[i][2]?1:0),0);progress.textContent='THIS WEEK / COMPLETE';const result=document.createElement('p');result.className='quiz-result';result.textContent=score+' / 3';const note=document.createElement('p');note.className='quiz-complete-note';note.textContent=(score===3?'You know your stuff. ': 'A few more details for your next car decision. ')+(persistent?'Your result is saved here. ':'This result cannot be saved in this browser. ')+'Come back Monday for the next set. Sets rotate every four weeks.';const replay=document.createElement('button');replay.type='button';replay.className='button quiz-next';replay.textContent='Try again';replay.addEventListener('click',()=>{state.answers=[];write(keys.quiz,state);draw();quiz.querySelector('button')?.focus();});quiz.append(progress,result,note,replay);return;}
    const index=state.answers.length;const [question,options,answer,explanation]=questions[index];progress.textContent=`QUESTION ${index+1} / 3`;const heading=document.createElement('p');heading.className='quiz-question';heading.textContent=question;const choices=document.createElement('div');choices.className='quiz-options';const feedback=document.createElement('p');feedback.className='quiz-explanation';feedback.setAttribute('role','status');const next=document.createElement('button');next.className='button quiz-next';next.type='button';next.hidden=true;next.textContent=index===2?'See my result ↗':'Next question ↗';next.addEventListener('click',()=>{draw();quiz.querySelector('button')?.focus();});options.forEach((option,i)=>{const b=document.createElement('button');b.type='button';b.textContent=option;b.addEventListener('click',()=>{choices.querySelectorAll('button').forEach((x,j)=>{x.disabled=true;if(j===answer)x.classList.add('correct');if(j===i&&i!==answer)x.classList.add('incorrect');});state.answers.push(i);write(keys.quiz,state);feedback.textContent=(i===answer?'Correct. ':'Not quite. Correct answer: '+options[answer]+'. ')+explanation;next.hidden=false;});choices.append(b);});quiz.append(progress,heading,choices,feedback,next);}
  draw();
})();
